const repos = $input.all().map(i => i.json);
const now = Date.now();
const J = 86400000;
const actifs = repos.filter(r => !r.archived);
const nbArchives = repos.length - actifs.length;

// Fenêtres de commit par niveau (règle de maintenance du 2026-09-15)
const NIVEAU1 = { "rennesdev": 7, "rennesdev-vps-ops": 7, "RuaudelEmmanuel.github.io": 7, "RuaudelPhoto": 7 };
const NIVEAU2 = { "Rennesdev-api": 14, "Fiscale-vps": 14, "Trombi": 14, "construction-site-tracker": 14,
                  "Besoin-visio": 14, "local_contextual_ai": 14, "ai_gemma_service": 14, "surveillance-tarifaire": 14 };

const lignes = actifs.map(r => {
  const jours = Math.floor((now - new Date(r.pushed_at).getTime()) / J);
  const age = jours <= 0 ? "aujourd'hui" : jours === 1 ? "hier" : `il y a ${jours} jours`;
  return `- ${r.name} (${r.private ? "privé" : "public"}) — dernier push ${age}${r.description ? " — " + r.description : ""}`;
});

// Radar de cadence : dépassement de fenêtre Niveau 1 / Niveau 2
const retards = [];
for (const [niveau, table] of [["N1", NIVEAU1], ["N2", NIVEAU2]]) {
  for (const [nom, fenetre] of Object.entries(table)) {
    const r = actifs.find(x => x.name === nom);
    if (!r) continue;
    const jours = Math.floor((now - new Date(r.pushed_at).getTime()) / J);
    if (jours > fenetre) retards.push(`- ⚠️ ${niveau} — ${nom} : ${jours} jours sans commit (fenêtre ${fenetre} j)`);
  }
}

const sansDesc = actifs.filter(r => !r.description).map(r => r.name);
const dormants = actifs.filter(r => (now - new Date(r.pushed_at).getTime()) > 60 * J
                                   && !(r.name in NIVEAU1) && !(r.name in NIVEAU2)).map(r => r.name);

const notes = [];
if (sansDesc.length) notes.push(`sans description : ${sansDesc.join(", ")}`);
if (dormants.length) notes.push(`dormants (plus de 60 jours, hors cadence suivie) : ${dormants.join(", ")}`);
if (!notes.length) notes.push("tous les repos ont une description et une activité correcte");

const cadence = retards.length
  ? `Cadence — dépassements de fenêtre de commit :\n${retards.join("\n")}`
  : "Cadence : tous les projets Niveau 1/2 respectent leur fenêtre de commit ✅";

return [{ json: { resume: `Repos GitHub d'Emmanuel (actifs : ${actifs.length}${nbArchives ? ", archivés : " + nbArchives : ""}) :\n\n${lignes.join("\n")}\n\n${cadence}\n\nSignaux : ${notes.join("; ")}` } }];
